#!/usr/bin/env node
/**
 * sync-solana-idl — regenerate lib/solana/idl.generated.ts from solana/idl/oilskin.json (itself copied from the
 * anchor build by solana/scripts/sync-idl.mjs and checked against the build in CI). The web encodes Solana
 * instructions ONLY from the generated file; test/solana-idl.test.ts re-reads the committed IDL and fails on
 * any drift — the same seam the ABI has (scripts/sync-abi.mjs).
 *
 *   node scripts/sync-solana-idl.mjs
 */
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const src = resolve(here, "../../solana/idl/oilskin.json");
const raw = readFileSync(src, "utf8");
const idl = JSON.parse(raw);
const sha256 = createHash("sha256").update(raw).digest("hex");

const flat = (accs, p = "") => accs.flatMap((a) => (a.accounts ? flat(a.accounts, p + a.name + ".") : [{ name: p + a.name, writable: !!a.writable, signer: !!a.signer, address: a.address ?? null }]));
const typeOf = (t) => (typeof t === "string" ? t : t.defined ? `defined:${t.defined.name}` : JSON.stringify(t));
const out = {
  address: idl.address,
  sha256,
  instructions: Object.fromEntries(idl.instructions.map((ix) => [ix.name, { discriminator: ix.discriminator, accounts: flat(ix.accounts), args: ix.args.map((a) => [a.name, typeOf(a.type)]) }])),
  accounts: Object.fromEntries(idl.accounts.map((a) => [a.name, a.discriminator])),
  types: Object.fromEntries(idl.types.filter((t) => ["GrantParams", "UserAccount", "Grant"].includes(t.name)).map((t) => [t.name, t.type.fields.map((f) => [f.name, typeOf(f.type)])])),
  errors: idl.errors.map((e) => ({ code: e.code, name: e.name, msg: e.msg })),
};
const body = `// GENERATED by scripts/sync-solana-idl.mjs from solana/idl/oilskin.json — do not edit by hand.\n// The web's Solana encoders read this and nothing else; test/solana-idl.test.ts fails on drift from the committed IDL.\nexport const OILSKIN_SOLANA_IDL = ${JSON.stringify(out, null, 2)} as const;\n`;
writeFileSync(resolve(here, "../lib/solana/idl.generated.ts"), body);
console.log(`wrote lib/solana/idl.generated.ts: ${Object.keys(out.instructions).length} instructions, ${Object.keys(out.accounts).length} accounts, ${out.errors.length} errors, sha256 ${sha256.slice(0, 12)}…`);
